CREATE FUNCTION public.narrow_repository_monitors(p_native_id bigint) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
    narrowed integer;
BEGIN
    UPDATE public.repository_to_monitor
    SET proof_generation = proof_generation + 1,
        visibility_class = CASE WHEN visibility_class = 'WORKSPACE' THEN 'UNPROVEN' ELSE visibility_class END,
        proof_state = CASE WHEN visibility_class = 'WORKSPACE' THEN 'PENDING' ELSE proof_state END,
        proof_reason = CASE WHEN visibility_class = 'WORKSPACE' THEN 'AWAITING_READERS' ELSE proof_reason END
    WHERE native_id = p_native_id;
    GET DIAGNOSTICS narrowed = ROW_COUNT;
    RETURN narrowed;
END
$$;
CREATE FUNCTION public.narrow_monitors_of_repository() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM public.narrow_repository_monitors(CASE WHEN TG_OP = 'DELETE' THEN OLD.native_id ELSE NEW.native_id END);
    RETURN NULL;
END
$$;
CREATE TRIGGER repository_not_public AFTER INSERT OR UPDATE ON public.repository
    FOR EACH ROW
    WHEN (NOT (NEW.visibility IS NOT DISTINCT FROM 'PUBLIC' AND NOT NEW.is_private))
    EXECUTE FUNCTION public.narrow_monitors_of_repository();
CREATE TRIGGER repository_gone AFTER DELETE ON public.repository
    FOR EACH ROW EXECUTE FUNCTION public.narrow_monitors_of_repository();
